#!/usr/bin/env python3
"""Build two blinded, local HTML forms from the reviewer packet."""
from __future__ import annotations

import argparse
import json
from pathlib import Path

from petlongevity_bench.io import load_jsonl

OPTIONS = {
    "label_decision": [("supported", "Supported — the quote directly justifies the claim"), ("contradicted", "Contradicted — the quote conflicts with the claim"), ("insufficient", "Insufficient — the quote does not establish the claim")],
    "species_decision": [("dog", "Dog"), ("cat", "Cat"), ("mouse", "Mouse"), ("human", "Human"), ("other", "Other")],
    "study_design_decision": [("RCT", "Randomized controlled trial (RCT)"), ("controlled trial", "Controlled trial"), ("cohort", "Cohort study"), ("observational", "Observational study"), ("case study", "Case study"), ("in vitro", "In vitro study"), ("review", "Review"), ("protocol", "Study protocol only")],
    "causal_status_decision": [("causal_supported", "Causal conclusion supported"), ("association_only", "Association only — does not show causation"), ("causal_not_established", "Causation not established"), ("not_applicable", "Not applicable")],
    "protocol_vs_result_decision": [("protocol", "Protocol / planned study"), ("completed_result", "Completed study result"), ("not_applicable", "Not applicable")],
    "evidence_strength_decision": [("high", "High"), ("moderate", "Moderate"), ("low", "Low"), ("very_low", "Very low")],
    "evidence_quote_verified": [("yes", "Yes — quote is present and accurate"), ("no", "No — quote is absent or inaccurate")],
    "source_support_quality": [("direct", "Direct — addresses the claim as stated"), ("partial", "Partial — supports only part of the claim"), ("indirect", "Indirect — requires an inference"), ("none", "None — does not support the chosen label")],
}


def build(packet: list[dict], output: Path, slot: str) -> None:
    data = json.dumps(packet, ensure_ascii=False).replace("</", "<\\/")
    choices = json.dumps({field: [{"value": value, "label": label} for value, label in values] for field, values in OPTIONS.items()})
    output.write_text(f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>PetLongevity review — {slot}</title>
<style>body{{font:16px system-ui;max-width:1050px;margin:auto;padding:24px;background:#f7f8fa;color:#17212b}}header{{position:sticky;top:0;background:#f7f8fa;padding:10px;border-bottom:1px solid #ddd;z-index:1}}button{{padding:9px 13px;margin:4px;border-radius:6px;border:1px solid #789;background:#fff;font-weight:600}}.card,.guide{{background:#fff;padding:22px;margin-top:18px;border-radius:10px;box-shadow:0 1px 3px #ccd}}.guide{{border-left:5px solid #2563eb}}label{{display:block;font-weight:700;margin-top:15px}}select,input,textarea{{font:16px system-ui;width:100%;box-sizing:border-box;padding:9px;margin-top:5px;border:1px solid #aab;border-radius:5px}}textarea{{min-height:80px}}.machine{{background:#fff7df;padding:14px;border-radius:6px}}.source{{background:#edf5ff;padding:14px;white-space:pre-wrap;border-radius:6px;line-height:1.45}}small,.help{{color:#475569;font-weight:400}}</style>
<header><b>Independent review — {slot}</b><br><small>This is research annotation, not clinical advice. Your review is private from the other reviewer.</small><br><button onclick="previous()">← Previous</button><button onclick="next()">Save & next →</button><button onclick="download()">Finish: validate & download</button> <span id="progress"></span></header>
<section class="guide"><h2>How to review each item</h2><ol><li>Read the claim.</li><li>Check the blue exact quote and nearby source context.</li><li>Make your own decision; the yellow machine proposal is only a suggestion.</li><li>Save and continue. You can work across sessions on the same browser.</li></ol><p><b>Key rule:</b> do not infer causality from association, lifespan benefit from a biomarker or surrogate, cat evidence from dog evidence, or efficacy from a protocol.</p><p>For detailed definitions, read <code>reviewer_guidelines.md</code> before starting.</p></section><main id="app"></main>
<script>const packet={data},slot={json.dumps(slot)},choices={choices},key='petbench-'+slot+'-v1';let i=+localStorage.getItem(key+'-index')||0,state=JSON.parse(localStorage.getItem(key)||'{{}}');const fields=['label_decision','species_decision','study_design_decision','causal_status_decision','protocol_vs_result_decision','evidence_strength_decision','evidence_quote_verified','source_support_quality'];const names={{label_decision:'Does the quote support the claim?',species_decision:'Which species does this evidence concern?',study_design_decision:'What type of study is this?',causal_status_decision:'What does this source establish about cause and effect?',protocol_vs_result_decision:'Is this a planned study or a completed result?',evidence_strength_decision:'How strong is the evidence for the claim?',evidence_quote_verified:'Is the exact quote present and accurate?',source_support_quality:'How directly does the quote support your decision?'}};function esc(x){{let d=document.createElement('div');d.textContent=x??'';return d.innerHTML}}function render(){{let p=packet[i],s=state[p.annotation_id]||{{}};progress.textContent=`Item ${{i+1}}/${{packet.length}}`;let h=`<section class=card><h2>Item ${{i+1}}: ${{esc(p.annotation_id)}}</h2><p><b>${{esc(p.paper_title)}}</b> (${{p.publication_year}}) · PMID ${{esc(p.pmid)}}</p><div class=machine><b>Machine proposal — do not copy automatically</b><br>Label: ${{esc(p.machine_gold_label)}} · design: ${{esc(p.machine_study_design)}} · causal: ${{esc(p.machine_causal_status)}} · protocol/result: ${{esc(p.machine_protocol_vs_result)}} · strength: ${{esc(p.machine_evidence_strength)}}<br><br><b>Claim to judge:</b> ${{esc(p.claim_text)}}</div><label>Exact evidence quote</label><div class=source>${{esc(p.evidence_quote)}}</div><label>Source context <span class=help>(${{esc(p.source_locator)}})</span></label><div class=source>${{esc(p.source_context)}}</div><label>Your reviewer ID <input id=reviewer_id placeholder="e.g. initials or assigned reviewer ID" value="${{esc(s.reviewer_id||'')}}"></label>`;for(let f of fields)h+=`<label>${{names[f]}}<select id=${{f}}><option value="">Choose an answer…</option>${{choices[f].map(x=>`<option value="${{esc(x.value)}}" ${{s[f]===x.value?'selected':''}}>${{esc(x.label)}}</option>`).join('')}}</select></label>`;h+=`<label>Your confidence <span class=help>(0 = not confident; 1 = fully confident)</span><input id=reviewer_confidence type=number min=0 max=1 step=.01 value="${{esc(s.reviewer_confidence||'')}}"></label><label>Your notes <span class=help>(briefly explain uncertainty or disagreement)</span><textarea id=reviewer_notes placeholder="Required — write a short review note.">${{esc(s.reviewer_notes||'')}}</textarea></label><button onclick="save()">Save this item</button></section>`;app.innerHTML=h}}function save(){{let p=packet[i],d={{annotation_id:p.annotation_id,reviewer_id:reviewer_id.value,review_timestamp:new Date().toISOString()}};for(let f of fields)d[f]=document.getElementById(f).value;d.reviewer_confidence=+reviewer_confidence.value;d.reviewer_notes=reviewer_notes.value;if(['reviewer_id',...fields,'reviewer_notes'].some(f=>d[f]==='')||Number.isNaN(d.reviewer_confidence)){{alert('Please complete every field before saving.');return false}}d._complete=true;state[p.annotation_id]=d;localStorage.setItem(key,JSON.stringify(state));return true}}function next(){{save();if(i<packet.length-1)i++;localStorage.setItem(key+'-index',i);render()}}function previous(){{save();if(i>0)i--;localStorage.setItem(key+'-index',i);render()}}function download(){{save();let rows=packet.map(p=>state[p.annotation_id]);if(rows.some(x=>!x||!x._complete)){{alert('Please complete all '+packet.length+' items before downloading.');return}}rows.forEach(x=>delete x._complete);let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(JSON.stringify).join('\\n')+'\\n'],{{type:'application/x-ndjson'}}));a.download=slot+'_decisions.jsonl';a.click()}}render();</script></html>''', encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--packet", default="review/reviewer_packet.jsonl")
    parser.add_argument("--output-dir", default="review")
    args = parser.parse_args()
    root = Path(args.output_dir)
    root.mkdir(parents=True, exist_ok=True)
    rows = load_jsonl(args.packet)
    for slot in ("reviewer_1", "reviewer_2"):
        build(rows, root / f"{slot}.html", slot)
